<?php
/** Explicit follow-up allowlist: disable the legacy editor only on the approved homepage. */
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
final class NativeHomepageMigration {
 const ID='007_use_native_homepage_content';
 public static function checksum(){return hash('sha256',file_get_contents(__FILE__));}
 public static function plan(){
  preflight();$config=payload();if(empty($config['approved'])||empty($config['homepage']['approve_replacement']))fail('Homepage replacement approval is required.');
  if((history()['003_apply_homepage_content']['status']??'')!=='completed')fail('Homepage content dependency incomplete.');
  $page=page($config['homepage']['path']);if(!current_user_can('edit_post',$page->ID))fail('Cannot edit the approved homepage.');
  if($page->post_content!==homepage_content())fail('Homepage content changed independently; review before disabling the legacy override.');
  $ops=[];foreach(['tcb_editor_disabled'=>['before'=>'','after'=>'1'],'tcb_editor_enabled'=>['before'=>'1','after'=>'']] as $key=>$expected){$actual=get_post_meta($page->ID,$key,true);if($actual!==$expected['before']&&$actual!==$expected['after'])fail('Editor flag conflict: '.$key);$ops[]=['key'=>$key,'id'=>$page->ID,'before'=>$actual,'after'=>$expected['after'],'action'=>$actual===$expected['after']?'already-satisfied':'update'];}return $ops;
 }
 public static function preview(){ $h=history()[self::ID]??[];if(isset($h['checksum'])&&$h['checksum']!==self::checksum())fail('Follow-up migration checksum changed.');$p=['checksum'=>self::checksum(),'actor'=>get_current_user_id(),'operations'=>self::plan(),'created'=>time()];update_option('edm_native_homepage_preview',$p,false);return $p; }
 public static function batch(){
  preflight();$token=lock_acquire();try{$h=history();$state=$h[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('Follow-up checksum changed.');if(($state['status']??'')==='completed'){self::plan();return ['status'=>'completed','message'=>'Native homepage migration already completed.'];}
   $p=get_option('edm_native_homepage_preview');if(!$p||$p['actor']!==get_current_user_id()||$p['checksum']!==self::checksum())fail('Fresh follow-up preview required.');$ops=self::plan();$h[self::ID]=array_merge($state,['status'=>'running','checksum'=>self::checksum(),'actor'=>get_current_user_id(),'run_id'=>$state['run_id']??wp_generate_uuid4(),'started'=>$state['started']??time(),'heartbeat'=>time(),'operations'=>$state['operations']??[]]);
   foreach($ops as $op){if(isset($h[self::ID]['operations'][$op['key']])){if($op['action']!=='already-satisfied')fail('Editor flag drift detected.');continue;} $expected=array_values(array_filter($p['operations'],fn($item)=>$item['key']===$op['key']))[0]??null;if(!$expected||($op['before']!==$expected['before']&&$op['action']!=='already-satisfied'))fail('Editor flag changed after preview.');lock_check($token);save_history($h);if($op['after']==='')delete_post_meta($op['id'],$op['key']);else update_post_meta($op['id'],$op['key'],$op['after']);if(get_post_meta($op['id'],$op['key'],true)!==$op['after'])fail('Editor flag postcondition failed.');lock_check($token);$h[self::ID]['operations'][$op['key']]=['status'=>'completed','destination_id'=>$op['id'],'before'=>$op['before'],'after_fingerprint'=>fingerprint($op['after']),'timestamp'=>time()];save_history($h);return ['status'=>'running','message'=>'Verified '.$op['key']];}
   foreach(self::plan() as $op)if($op['action']!=='already-satisfied')fail('Native homepage postcondition failed.');$h[self::ID]['status']='completed';$h[self::ID]['completed']=time();save_history($h);return ['status'=>'completed','message'=>'Native homepage content enabled; old builder content retained.'];
  }catch(\Throwable $e){$h=history();$h[self::ID]=array_merge($h[self::ID]??[],['status'=>'failed','checksum'=>self::checksum(),'error'=>$e->getMessage()]);save_history($h);throw $e;}finally{lock_release($token);}
 }
}
// This separate immutable extension preserves the six completed migration checksums.
add_action('admin_post_edm_native_preview',function(){if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('edm_native_preview');try{NativeHomepageMigration::preview();}catch(\Throwable $e){update_option('edm_native_homepage_notice',$e->getMessage(),false);}wp_safe_redirect(admin_url('tools.php?page=eyedonation-migrations'));exit;});
add_action('wp_ajax_edm_native_batch',function(){if(!current_user_can('manage_options'))wp_send_json_error(['message'=>'Unauthorized'],403);check_ajax_referer('edm_run');if(empty($_POST['backup']))wp_send_json_error(['message'=>'Backup acknowledgment required.'],400);try{wp_send_json_success(NativeHomepageMigration::batch());}catch(\Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],409);}});
add_action('admin_menu',function(){remove_action('tools_page_eyedonation-migrations',__NAMESPACE__.'\\admin_screen');remove_submenu_page('tools.php','eyedonation-migrations');add_management_page('Site Migrations','Site Migrations','manage_options','eyedonation-migrations',function(){admin_screen();$h=history()[NativeHomepageMigration::ID]??[];$p=get_option('edm_native_homepage_preview');echo '<div class="wrap"><h2>007 — Use native homepage content</h2><p>Disables the legacy editor override only on the approved homepage. Preserves saved builder content and all other pages. Dependency: 003. Status: '.esc_html($h['status']??'pending').'</p><p role="status">'.esc_html(get_option('edm_native_homepage_notice','')).'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="edm_native_preview">';wp_nonce_field('edm_native_preview');submit_button('Preview Changes');echo '</form>';if($p)echo '<pre>'.esc_html(wp_json_encode($p['operations'],JSON_PRETTY_PRINT)).'</pre>';echo '<button class="button" type="button" id="edm-native-run" '.(!$p?'disabled':'').'>Process / Resume native homepage migration</button></div>';wp_enqueue_script('edm-native-admin',plugins_url('../assets/native-homepage.js',__FILE__),['edm-admin'],VERSION,true);});},99);
